const successionBytes=readFileSync(new URL('./fixtures/release18-lower/display-pin-c32-succession.json',import.meta.url));
assert.equal(sha(successionBytes),'d11bf0d9f1daf4b0cc784181f871195730ba65be257fc8e3dcf0ae86c13c2c39',
 'Authenticated post-b79 display-pin succession');
const succession=JSON.parse(successionBytes);
assert.equal(succession.schema,'vm-lower-display-pin-c32-succession/1');
assert.equal(succession.from,'b79e110d2d28f18993263926ba35aa7a3f478b20');
assert.equal(succession.to,'c32bc81cf0fd7ec22fa83e8b1365019297f9a0b3');
assert.equal(succession.path,file);
assert.equal(succession.fromSha256,laterPinEpochs.at(-1)[1]);
assert.equal(succession.toSha256,'34c9aadb624d2b8dd073736c997ad7d87d8aef549755ca2d8ef46706b590acb7');
assert.equal(succession.rows.length,21,'Every subsequent pin-changing source commit is declared');

assert.equal(sha(readGit(succession.from,file)),succession.fromSha256,'Complete authenticated b79 document');
assert.equal(revision,succession.to,'Exact current source epoch');
for(const row of succession.rows){
 const source=readGit(row.commit,file);
 assert.equal(sha(source),row.sha256,'Exact subsequent display-pin bytes: '+row.commit);
 const next=map(source),ids=changed(previous,next);
 assert.equal(ids.length,row.changedCount,'Exact subsequent pin-change count: '+row.commit);
 assert.equal(sha(JSON.stringify(ids)),row.changedIdsSha256,'Exact subsequent changed IDs: '+row.commit);
 transitions.push({source:row.commit,ids});previous=next;
}
assert.equal(succession.rows.at(-1).commit,revision,'No terminal source omitted');
assert.equal(sha(currentBytes),succession.toSha256,'Current imported document must equal the complete declared source epoch');
assert.deepEqual(current,previous,'Unrecognized current display-pin changes require an explicit source-bound history');

assert.deepEqual(result.transitions.slice(0,14).map(r=>r.ids.length),[2,3,5,22,6,3,8,6,8,12,12,12,20,8],
 'All original historical pin transitions remain exact');
assert.deepEqual(result.transitions.slice(14).map(r=>r.ids.length),succession.rows.map(r=>r.changedCount));
assert.deepEqual(result.transitions.slice(14).map(r=>r.source),succession.rows.map(r=>r.commit));
const commits=execFileSync('git',['log','--reverse','--format=%H',succession.from+'..'+CURRENT_ATLAS_REVISION,
 '--','content/body-review-display-pins.json'],{cwd:root,encoding:'utf8',windowsHide:true,
 env:{...process.env,GIT_NO_REPLACE_OBJECTS:'1'}}).trim().split('\n');
assert.deepEqual(commits,succession.rows.map(r=>r.commit),'Every actual subsequent pin-changing commit admitted');
assert.equal(sha(bytes),succession.toSha256,'Current imported full document');
